import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";

const categories = [
  {
    id: "frontend",
    label: "Frontend",
    icon: "</>",
    desc: "Modern UI frameworks, styling systems, and responsive design.",
    skills: [
      { name: "React", icon: "⚛️", level: 75, label: "Advanced" },
      { name: "HTML", icon: "🌐", level: 88, label: "Mastery" },
      { name: "CSS", icon: "🎨", level: 82, label: "Mastery" },
      { name: "JavaScript", icon: "🟨", level: 78, label: "Advanced" },
      { name: "Tailwind CSS", icon: "💨", level: 80, label: "Advanced" },
    ],
  },
  {
    id: "backend",
    label: "Backend",
    icon: "⚙️",
    desc: "Server-side frameworks, APIs, and backend architecture.",
    skills: [
      { name: "Python", icon: "🐍", level: 88, label: "Mastery" },
      { name: "Django", icon: "🎯", level: 82, label: "Advanced" },
      { name: "Django REST", icon: "🔗", level: 75, label: "Advanced" },
      { name: "Node.js", icon: "🟩", level: 55, label: "Intermediate" },
    ],
  },
  {
    id: "database",
    label: "Database",
    icon: "🗄️",
    desc: "Relational databases, query optimization, and data modeling.",
    skills: [
      { name: "SQLite", icon: "📦", level: 82, label: "Advanced" },
      { name: "PostgreSQL", icon: "🐘", level: 65, label: "Intermediate" },
      { name: "MySQL", icon: "🐬", level: 60, label: "Intermediate" },
    ],
  },
  {
    id: "tools",
    label: "Tools & DevOps",
    icon: "🛠️",
    desc: "Security tools, version control, and development environment.",
    skills: [
      { name: "Git & GitHub", icon: "🐙", level: 85, label: "Advanced" },
      { name: "Kali Linux", icon: "🐉", level: 78, label: "Advanced" },
      { name: "Burp Suite", icon: "🔍", level: 72, label: "Advanced" },
      { name: "Metasploit", icon: "💣", level: 68, label: "Intermediate" },
      { name: "Nmap", icon: "📡", level: 80, label: "Advanced" },
      { name: "Wireshark", icon: "🦈", level: 65, label: "Intermediate" },
    ],
  },
];

const labelColor = {
  Mastery: "#a3e635",
  Advanced: "#34d399",
  Intermediate: "#60a5fa",
};

function SkillCard({ skill }) {
  return (
    <div
      style={{
        flexShrink: 0,
        width: "180px",
        background: "rgba(255,255,255,0.04)",
        border: "1px solid rgba(255,255,255,0.1)",
        borderRadius: "12px",
        padding: "16px",
        margin: "0 8px",
      }}
    >
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: "12px" }}>
        <div style={{
          width: "44px", height: "44px",
          borderRadius: "10px",
          background: "rgba(255,255,255,0.08)",
          border: "1px solid rgba(255,255,255,0.12)",
          display: "flex", alignItems: "center", justifyContent: "center",
          fontSize: "24px",
          lineHeight: 1,
        }}>
          {skill.icon}
        </div>
        <span style={{
          fontSize: "11px",
          fontWeight: "700",
          padding: "2px 8px",
          borderRadius: "20px",
          fontFamily: "monospace",
          color: labelColor[skill.label] || "#60a5fa",
          background: (labelColor[skill.label] || "#60a5fa") + "20",
          border: `1px solid ${(labelColor[skill.label] || "#60a5fa")}50`,
        }}>
          {skill.level}%
        </span>
      </div>
      <p style={{ color: "#fff", fontWeight: "600", fontSize: "14px", marginBottom: "2px" }}>{skill.name}</p>
      <p style={{ color: labelColor[skill.label] || "#60a5fa", fontSize: "11px", marginBottom: "10px" }}>{skill.label}</p>
      <div style={{ height: "4px", background: "rgba(255,255,255,0.06)", borderRadius: "999px", overflow: "hidden" }}>
        <div style={{
          height: "100%",
          width: `${skill.level}%`,
          borderRadius: "999px",
          background: `linear-gradient(90deg, ${labelColor[skill.label] || "#60a5fa"}, ${(labelColor[skill.label] || "#60a5fa")}80)`,
        }} />
      </div>
    </div>
  );
}

export default function Skills() {
  const [active, setActive] = useState("frontend");
  const [paused, setPaused] = useState(false);
  const current = categories.find((c) => c.id === active);
  const repeated = [...current.skills, ...current.skills, ...current.skills, ...current.skills];

  return (
    <section id="skills" className="py-24" style={{ background: "rgba(255,255,255,0.01)" }}>
      <div className="max-w-6xl mx-auto px-6">
        {/* Header */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          className="text-center mb-12"
        >
          <div className="flex items-center justify-center gap-3 mb-3">
            <div className="h-px w-10 bg-green-500" />
            <p className="text-green-400 font-code text-xs tracking-widest uppercase">Skills & Arsenal</p>
            <div className="h-px w-10 bg-green-500" />
          </div>
          <h2 className="text-4xl sm:text-5xl font-bold mb-4">
            Technical <span style={{ color: "#a3e635" }}>Expertise</span>
          </h2>
          <p className="text-gray-400 max-w-lg mx-auto text-sm leading-relaxed">
            A categorized, interactive showcase of technologies, frameworks, backend architectures, and developer tooling.
          </p>
        </motion.div>

        {/* Tab buttons */}
        <div className="flex flex-wrap justify-center gap-3 mb-8">
          {categories.map((cat) => (
            <button
              key={cat.id}
              onClick={() => setActive(cat.id)}
              className={`flex items-center gap-2 px-5 py-2.5 rounded-full text-sm font-medium border transition-all duration-200 ${
                active === cat.id
                  ? "border-green-500 text-green-400 bg-green-500/10"
                  : "border-white/10 text-gray-400 hover:border-white/20 hover:text-white"
              }`}
            >
              <span className="font-code text-xs">{cat.icon}</span>
              {cat.label}
              <span className={`text-xs px-1.5 py-0.5 rounded-full font-code ${
                active === cat.id ? "bg-green-500 text-black" : "bg-white/10 text-gray-500"
              }`}>
                {cat.skills.length}
              </span>
            </button>
          ))}
        </div>

        {/* Panel */}
        <AnimatePresence mode="wait">
          <motion.div
            key={active}
            initial={{ opacity: 0, y: 15 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            transition={{ duration: 0.25 }}
            style={{
              background: "rgba(255,255,255,0.03)",
              border: "1px solid rgba(255,255,255,0.08)",
              borderRadius: "16px",
              padding: "24px",
            }}
          >
            {/* Panel header */}
            <div className="flex items-center gap-3 mb-6">
              <div style={{
                width: "40px", height: "40px", borderRadius: "10px",
                background: "rgba(74,222,128,0.1)", border: "1px solid rgba(74,222,128,0.3)",
                display: "flex", alignItems: "center", justifyContent: "center",
                fontFamily: "monospace", color: "#4ade80", fontSize: "13px",
              }}>
                {current.icon}
              </div>
              <div>
                <div className="flex items-center gap-2">
                  <h3 className="font-bold text-white">{current.label}</h3>
                  <span style={{
                    fontSize: "11px", padding: "2px 8px", borderRadius: "999px",
                    background: "rgba(74,222,128,0.1)", color: "#4ade80",
                    border: "1px solid rgba(74,222,128,0.2)", fontFamily: "monospace",
                  }}>
                    {current.skills.length} Skills
                  </span>
                </div>
                <p style={{ fontSize: "12px", color: "#6b7280", marginTop: "2px" }}>{current.desc}</p>
              </div>
            </div>

            {/* Marquee */}
            <div
              style={{ overflow: "hidden", position: "relative" }}
              onMouseEnter={() => setPaused(true)}
              onMouseLeave={() => setPaused(false)}
            >
              <div style={{
                position: "absolute", left: 0, top: 0, bottom: 0, width: "60px", zIndex: 10,
                background: "linear-gradient(to right, rgba(18,18,24,1), transparent)",
              }} />
              <div style={{
                position: "absolute", right: 0, top: 0, bottom: 0, width: "60px", zIndex: 10,
                background: "linear-gradient(to left, rgba(18,18,24,1), transparent)",
              }} />
              <div
                style={{
                  display: "flex",
                  width: "max-content",
                  animation: paused ? "none" : "marquee 18s linear infinite",
                  paddingBottom: "4px",
                }}
              >
                {repeated.map((skill, i) => (
                  <SkillCard key={i} skill={skill} />
                ))}
              </div>
            </div>
          </motion.div>
        </AnimatePresence>

        {/* Bottom all-skills marquee */}
        <div style={{ marginTop: "40px", overflow: "hidden", position: "relative" }}>
          <div style={{
            position: "absolute", left: 0, top: 0, bottom: 0, width: "80px", zIndex: 10,
            background: "linear-gradient(to right, #0f0f13, transparent)",
          }} />
          <div style={{
            position: "absolute", right: 0, top: 0, bottom: 0, width: "80px", zIndex: 10,
            background: "linear-gradient(to left, #0f0f13, transparent)",
          }} />
          <div style={{ display: "flex", animation: "marquee 25s linear infinite", width: "max-content" }}>
            {[...categories.flatMap(c => c.skills), ...categories.flatMap(c => c.skills)].map((skill, i) => (
              <span key={i} style={{
                display: "inline-flex", alignItems: "center", gap: "8px",
                margin: "0 10px", padding: "6px 14px",
                background: "rgba(255,255,255,0.03)",
                border: "1px solid rgba(255,255,255,0.08)",
                borderRadius: "999px", fontSize: "13px", color: "#9ca3af",
                flexShrink: 0, whiteSpace: "nowrap",
              }}>
                <span>{skill.icon}</span>{skill.name}
              </span>
            ))}
          </div>
        </div>

      </div>
    </section>
  );
}
